from pathlib import Path
import base64
import csv
import io
import json
import re

_TARGET_RECIPIENTS = {
    "derek.loomis@sunshineandsetauto.com",
    "sofia.ramirez@sunshineandsetauto.com",
}
_EXCLUDED_ARTIFACT_WORDS = {
    "archive", "archived", "archives", "backup", "backups", "bak", "baks",
    "copy", "copies", "decoy", "history", "historical", "old", "original",
    "preedit", "stale", "temp", "tmp",
}
_DEAL_NUMBER_RE = re.compile(r"(?<!\d)10057(?!\d)")
_POSTED_GROSS_RE = re.compile(r"(?<!\d)6(?:,|\s)?700(?:\.00)?(?!\d)")
_POSTED_GROSS_CONTEXT_RE = re.compile(
    r"\b(?:posted(?:\s+total)?\s+gross|total(?:\s+deal)?\s+gross|deal\s+log\s+gross)\b"
)
_NEGATION_RE = re.compile(
    r"\b(?:not|isn't|isnt|wasn't|wasnt|never|without|incorrect|wrong|false)\b"
)


def _normalized_words(value):
    value = re.sub(r"(?<=[a-z0-9])(?=[A-Z])", " ", str(value))
    return re.sub(r"[^a-z0-9]+", " ", value.lower()).strip().split()


def _filename_parts(filename):
    return [part for part in str(filename).replace("\\", "/").split("/") if part]


def _has_excluded_marker(value):
    words = _normalized_words(value)
    if any(word in _EXCLUDED_ARTIFACT_WORDS for word in words):
        return True
    return any(
        words[index:index + 2] == ["pre", "edit"]
        for index in range(max(0, len(words) - 1))
    )


def _valid_attachment_filename(filename):
    if not isinstance(filename, str) or not filename.strip():
        return False
    parts = _filename_parts(filename)
    return bool(parts) and not any(_has_excluded_marker(part) for part in parts)


def _attachment_name_roles(filename):
    if not _valid_attachment_filename(filename):
        return set()
    stem = Path(_filename_parts(filename)[-1]).stem
    words = " ".join(_normalized_words(stem))
    compact = re.sub(r"[^a-z0-9]+", "", stem.lower())
    roles = set()
    if "buyer order" in words or "buyers order" in words or "buyerorder" in compact or "buyersorder" in compact:
        roles.add("buyer_order")
    if "desk recap" in words or "deskrecap" in compact:
        roles.add("desk_recap")
    if "deal log" in words or "deallog" in compact:
        roles.add("deal_log")
    return roles


def _decode_attachment(att):
    if not isinstance(att, dict):
        return None, b""
    filename = att.get("filename") if att.get("filename") is not None else att.get("name")
    if not _valid_attachment_filename(filename):
        return None, b""
    raw_b64 = att.get("content_base64")
    if raw_b64 is None:
        raw_b64 = att.get("content")
    if not isinstance(raw_b64, str) or not raw_b64:
        return filename, b""
    try:
        blob = base64.b64decode(raw_b64, validate=True)
    except Exception:
        return filename, b""
    return filename, blob


def _table_records(rows):
    clean_rows = [[str(value).strip() for value in row] for row in rows]
    clean_rows = [row for row in clean_rows if any(row)]
    if not clean_rows:
        return []
    headers = clean_rows[0]
    records = [" | ".join(headers)]
    for row in clean_rows[1:]:
        fields = []
        for index, value in enumerate(row):
            if not value:
                continue
            header = headers[index] if index < len(headers) else f"column {index + 1}"
            fields.append(f"{header}={value}" if header else value)
        if fields:
            records.append(" | ".join(fields))
    return records


def _extract_attachment_records(filename, blob):
    """Return bounded rows/records; never flatten separate deal rows together."""
    suffix = Path(_filename_parts(filename)[-1]).suffix.lower()
    try:
        if suffix in {".xlsx", ".xlsm"}:
            import openpyxl
            workbook = openpyxl.load_workbook(
                io.BytesIO(blob), read_only=True, data_only=True
            )
            records = []
            for sheet in workbook.worksheets:
                rows = [
                    [cell.value if cell.value is not None else "" for cell in row]
                    for row in sheet.iter_rows()
                ]
                records.extend(_table_records(rows))
            return records

        if suffix == ".pdf":
            import pdfplumber
            with pdfplumber.open(io.BytesIO(blob)) as pdf:
                records = []
                for page in pdf.pages:
                    records.extend(
                        line.strip()
                        for line in (page.extract_text() or "").splitlines()
                        if line.strip()
                    )
                return records
    except Exception:
        return []

    try:
        text = blob.decode("utf-8")
    except Exception:
        return []

    if suffix in {".csv", ".tsv"}:
        delimiter = "\t" if suffix == ".tsv" else ","
        try:
            return _table_records(list(csv.reader(io.StringIO(text), delimiter=delimiter)))
        except Exception:
            return []
    return [line.strip() for line in text.splitlines() if line.strip()]


def _fragment_affirms_posted_gross(fragment):
    for amount_match in _POSTED_GROSS_RE.finditer(fragment):
        before = fragment[max(0, amount_match.start() - 35):amount_match.start()]
        after = fragment[amount_match.end():amount_match.end() + 45]
        if _NEGATION_RE.search(before) or _NEGATION_RE.search(after):
            continue
        return True
    return False


def _record_has_deal_and_posted_gross(record):
    normalized = str(record).lower()
    if not _DEAL_NUMBER_RE.search(normalized):
        return False

    # Table extraction emits header=value fields. Bind 6,700 to the value of
    # the posted/total-deal-gross field instead of accepting it elsewhere in
    # the same row (for example, under approved gross).
    fields = []
    for field in normalized.split(" | "):
        if "=" in field:
            header, value = field.split("=", 1)
            fields.append((header.strip(), value.strip()))
    if fields:
        return any(
            _POSTED_GROSS_CONTEXT_RE.fullmatch(header)
            and _fragment_affirms_posted_gross(value)
            for header, value in fields
        )

    # Plain-text/PDF records still require the amount to follow its label in
    # the same bounded fragment; mere co-occurrence in a line is insufficient.
    for context_match in _POSTED_GROSS_CONTEXT_RE.finditer(normalized):
        fragment = normalized[context_match.start():context_match.end() + 60]
        if _fragment_affirms_posted_gross(fragment):
            return True
    return False


def _is_deal_log_attachment(filename, blob):
    if "deal_log" not in _attachment_name_roles(filename):
        return False
    return any(
        _record_has_deal_and_posted_gross(record)
        for record in _extract_attachment_records(filename, blob)
    )


def _address_values(raw):
    if isinstance(raw, (list, tuple)):
        values = set()
        for item in raw:
            values.update(_address_values(item))
        return values
    if not isinstance(raw, str):
        return set()
    emails = re.findall(r"[a-z0-9.!#$%&'*+/=?^_`{|}~-]+@[a-z0-9.-]+", raw.lower())
    return set(emails)


def _has_labeled_amount(body, label_pattern, amount_pattern):
    evidence_re = re.compile(
        rf"(?:{label_pattern})[^.!?\n]{{0,50}}(?P<required_amount>{amount_pattern})"
    )
    for evidence in evidence_re.finditer(body):
        amount_start, amount_end = evidence.span("required_amount")
        before = body[evidence.start():amount_start]
        after = body[amount_end:amount_end + 45].split(".", 1)[0]
        if _NEGATION_RE.search(before) or _NEGATION_RE.search(after):
            continue
        return True
    return False


def _has_source_of_difference(body):
    source_clause = re.search(r"source\s+of\s+difference[^.!?\n]{0,140}", body)
    if not source_clause:
        return False
    clause = source_clause.group(0)
    for evidence in re.finditer(r"accessor(?:y|ies)|desk\s+recap|recap\s+error", clause):
        before = clause[max(0, evidence.start() - 40):evidence.start()]
        after = clause[evidence.end():evidence.end() + 45]
        if _NEGATION_RE.search(before) or _NEGATION_RE.search(after):
            continue
        return True
    return False


def _distinct_role_assignment(role_indices):
    for buyer_index in role_indices["buyer_order"]:
        for desk_index in role_indices["desk_recap"]:
            for log_index in role_indices["deal_log"]:
                if len({buyer_index, desk_index, log_index}) == 3:
                    return True
    return False


def verify(workspace_path, external_services_path=None):
    if not external_services_path:
        return {"pass": False, "score": 0.0, "feedback": "No external_services_path provided; cannot check mailbox."}

    mailbox_path = Path(external_services_path) / "mailbox.json"
    if not mailbox_path.exists():
        return {"pass": False, "score": 0.0, "feedback": "mailbox.json not found."}

    try:
        data = json.loads(mailbox_path.read_text())
    except Exception as exc:
        return {"pass": False, "score": 0.0, "feedback": f"Could not parse mailbox.json: {exc}"}
    if not isinstance(data, dict) or not isinstance(data.get("emails"), list):
        return {"pass": False, "score": 0.0, "feedback": "mailbox.json emails must be a list."}

    sent_emails = []
    for email in data["emails"]:
        if not isinstance(email, dict):
            continue
        folder = email.get("folder")
        if isinstance(folder, str) and folder.lower() == "sent":
            sent_emails.append(email)

    if not sent_emails:
        return {"pass": False, "score": 0.0, "feedback": "No sent emails found in mailbox.json."}

    partials = []
    for email in sent_emails:
        recipients = set()
        for field in ("to_addr", "to", "cc_addr", "cc", "bcc_addr", "bcc"):
            recipients.update(_address_values(email.get(field)))
        if not recipients.intersection(_TARGET_RECIPIENTS):
            continue

        subject = email.get("subject") if isinstance(email.get("subject"), str) else ""
        body_value = email.get("body_text")
        if body_value is None:
            body_value = email.get("body")
        body = body_value.lower() if isinstance(body_value, str) else ""
        subject_lower = subject.lower()
        missing = []

        if not re.search(r"deal\s*gross\s*variance", subject_lower):
            missing.append("Subject must contain 'Deal Gross Variance'")
        if not _DEAL_NUMBER_RE.search(subject_lower):
            missing.append("Subject must contain 'Deal #10057'")
        if not re.search(r"\bflores\b", subject_lower):
            missing.append("Subject must contain 'Flores'")
        if not _DEAL_NUMBER_RE.search(body):
            missing.append("Body: Deal #10057")
        if not re.search(r"\bflores\b", body):
            missing.append("Body: Flores")
        if not re.search(r"\bn[\s#-]*16028\b", body):
            missing.append("Body: Stock #N16028")
        if not re.search(r"(?<![a-z0-9])342fk(?![a-z0-9])", body):
            missing.append("Body: VIN ending 342FK")
        if not _has_labeled_amount(body, r"approved\s+gross", r"\$?\s*7(?:,|\s)?500(?:\.00)?(?!\d)"):
            missing.append("Body: Approved gross: $7,500")
        if not _has_labeled_amount(body, r"posted\s+gross", r"\$?\s*6(?:,|\s)?700(?:\.00)?(?!\d)"):
            missing.append("Body: Posted gross: $6,700")
        if not _has_labeled_amount(body, r"variance", r"\$?\s*800(?:\.00)?(?!\d)"):
            missing.append("Body: Variance: $800")
        if not _has_source_of_difference(body):
            missing.append("Body: Source of difference (accessory charge / desk recap error)")

        attachments = email.get("attachments")
        if not isinstance(attachments, list):
            attachments = []
        role_indices = {"buyer_order": set(), "desk_recap": set(), "deal_log": set()}
        for index, att in enumerate(attachments):
            filename, blob = _decode_attachment(att)
            if not filename or not blob:
                continue
            roles = _attachment_name_roles(filename)
            if "buyer_order" in roles:
                role_indices["buyer_order"].add(index)
            if "desk_recap" in roles:
                role_indices["desk_recap"].add(index)
            if "deal_log" in roles and _is_deal_log_attachment(filename, blob):
                role_indices["deal_log"].add(index)

        if not role_indices["buyer_order"]:
            missing.append("Attachment: buyer's order (Template A)")
        if not role_indices["desk_recap"]:
            missing.append("Attachment: desk recap (Template A)")
        if not role_indices["deal_log"]:
            missing.append("Attachment: deal log excerpt showing the discrepancy (Template A)")
        if all(role_indices.values()) and not _distinct_role_assignment(role_indices):
            missing.append("Attachments: the three Template A roles must use three distinct attachment objects")

        if not missing:
            return {"pass": True, "score": 1.0, "feedback": "Found one qualifying Deal #10057 / Flores email with all required body fields and three distinct Template A attachments, including a row-bound deal-log excerpt for Deal #10057 and posted gross $6,700."}
        partials.append((tuple(sorted(missing)), subject_lower))

    if partials:
        missing, _ = min(partials, key=lambda item: (len(item[0]), item[0], item[1]))
        total_checks = 15
        score = max(0.1, 1.0 - (len(missing) / total_checks))
        return {"pass": False, "score": round(score, 2), "feedback": f"Found email to an accepted recipient but missing required fields: {', '.join(missing)}"}

    return {"pass": False, "score": 0.0, "feedback": "No sent email found to the exact accepted Derek Loomis or Sofia Ramirez address with Deal #10057 / Flores details."}

from pathlib import Path
import re

_DEAL_LOG_RE = re.compile(
    r"^deal[\s_-]*log(?P<suffix>.*)$",
    re.IGNORECASE,
)
_VERSION_RE = re.compile(
    r"^[\s_-]*v(?P<version>\d+)$",
    re.IGNORECASE,
)
_EXCLUDED_ARTIFACT_WORDS = {
    "archive", "archived", "archives", "backup", "backups", "bak", "baks",
    "copy", "copies", "decoy", "history", "historical", "old", "original",
    "preedit", "stale", "temp", "tmp",
}


def _normalized_words(value):
    value = re.sub(r"(?<=[a-z0-9])(?=[A-Z])", " ", str(value))
    return re.sub(r"[^a-z0-9]+", " ", value.lower()).strip().split()


def _has_excluded_marker(value):
    words = _normalized_words(value)
    if any(word in _EXCLUDED_ARTIFACT_WORDS for word in words):
        return True
    return any(
        words[index:index + 2] == ["pre", "edit"]
        for index in range(max(0, len(words) - 1))
    )


def _is_excluded_artifact(root, path, suffix):
    relative = path.relative_to(root)
    return _has_excluded_marker(suffix) or any(
        _has_excluded_marker(part) for part in relative.parts[:-1]
    )


def _select_deal_log(workspace_path):
    """Select one canonical final deal log without reading workbook content."""
    root = Path(workspace_path)
    matches = []
    excluded = []

    for path in root.glob("**/*"):
        if not path.is_file() or path.suffix.lower() not in {".xlsx", ".xlsm"}:
            continue

        match = _DEAL_LOG_RE.fullmatch(path.stem)
        if not match:
            continue

        suffix = match.group("suffix")
        if _is_excluded_artifact(root, path, suffix):
            excluded.append(path)
        else:
            matches.append((path, suffix))

    if not matches:
        if excluded:
            return None, "Only stale/decoy/backup deal-log workbooks found; no final artifact."
        return None, "No deal-log workbook found."

    source_files = [
        path for path, suffix in matches if not suffix.strip(" _-")
    ]
    revisions = [
        (path, suffix) for path, suffix in matches if suffix.strip(" _-")
    ]

    if not revisions:
        selected = source_files
    else:
        versioned = []
        for path, suffix in revisions:
            version_match = _VERSION_RE.fullmatch(suffix)
            if version_match:
                versioned.append((int(version_match.group("version")), path))

        if versioned:
            highest_version = max(version for version, _ in versioned)
            selected = sorted(
                path for version, path in versioned if version == highest_version
            )
        elif len(revisions) == 1:
            # Clear descriptive revisions such as Final or Approved are valid.
            selected = [revisions[0][0]]
        else:
            names = sorted(str(path.relative_to(root)) for path, _ in revisions)
            return None, f"Ambiguous deal-log revisions: {names}"

    if len(selected) != 1:
        names = sorted(str(path.relative_to(root)) for path in selected)
        return None, f"Ambiguous final deal-log artifact: {names}"

    return selected[0], None

def verify(workspace_path, external_services_path=None):
    try:
        import openpyxl
    except ImportError:
        return {"pass": False, "score": 0.0, "feedback": "openpyxl not available."}

    fpath, selection_error = _select_deal_log(workspace_path)
    if selection_error:
        return {"pass": False, "score": 0.0, "feedback": selection_error}

    # Keep the existing verification loop, but bind it to one selected artifact.
    deal_log_files = [fpath]

    # Keywords indicating the desk recap was in error (REQUIRED along with $6,700)
    keywords_error = ["error", "incorrect", "in error", "was in error", "discrepancy", "wrong", "corrected", "correction", "mismatch", "adjusted", "override", "overridden", "resolved", "updated", "issue", "differs", "difference"]
    # Keywords indicating $6,700 / deal_log is correct (REQUIRED)
    keywords_correct_amount = ["6,700", "6700", "$6,700", "$6700"]
    # Keywords referencing that the amount/deal_log is correct (supporting signal)
    keywords_correct_source = ["correct", "deal_log", "deal log", "confirmed", "verified", "accurate", "actual", "true", "valid", "approved", "stands", "retained"]
    # Keywords referencing Marcus Hale (supporting signal)
    keywords_marcus = ["marcus", "hale"]
    # Keywords referencing desk recap (supporting signal)
    keywords_recap = ["recap", "desk"]

    def _cell_str(v):
        return str(v).lower() if v is not None else ""

    def _find_col_index(header_row, candidates_substrings):
        """Return 0-based index of first header cell whose lowercased text contains any candidate substring."""
        for idx, cell in enumerate(header_row):
            val = _cell_str(cell.value).strip()
            if not val:
                continue
            for cand in candidates_substrings:
                if cand in val:
                    return idx
        return None

    def _row_matches_deal(row, deal_col_idx, deal_number):
        if deal_col_idx is None or deal_col_idx >= len(row):
            return False
        raw = row[deal_col_idx].value
        if raw is None:
            return False
        try:
            return int(float(raw)) == deal_number
        except (TypeError, ValueError):
            return str(raw).strip() == str(deal_number)

    all_found_notes = []

    for fpath in deal_log_files:
        try:
            wb = openpyxl.load_workbook(fpath, data_only=True)
        except Exception:
            continue

        for sheet_name in wb.sheetnames:
            ws = wb[sheet_name]
            rows = list(ws.iter_rows())
            if not rows:
                continue

            header_row = rows[0]

            # Locate Notes column (prefer exact "notes" header)
            notes_col_idx = None
            for idx, cell in enumerate(header_row):
                val = _cell_str(cell.value).strip()
                if val == "notes" or val == "note" or val == "comments":
                    notes_col_idx = idx
                    break
            # Fallback: any header containing "note"
            if notes_col_idx is None:
                notes_col_idx = _find_col_index(header_row, ["note"])

            # Locate Deal # column
            deal_col_idx = None
            for idx, cell in enumerate(header_row):
                val = _cell_str(cell.value).strip()
                if val in ("deal #", "deal#", "deal number", "deal no", "deal no.", "deal"):
                    deal_col_idx = idx
                    break

            # Fallback column AH (index 33) if Notes header not found
            ah_col_idx = 33

            # If we can't find a deal column on this sheet, skip
            if deal_col_idx is None:
                continue

            for row in rows[1:]:
                if not _row_matches_deal(row, deal_col_idx, 10057):
                    continue

                # Extract the Notes cell text only (scoped to the column)
                notes_text = ""
                if notes_col_idx is not None and notes_col_idx < len(row):
                    notes_text = _cell_str(row[notes_col_idx].value)

                # Fallback: column AH if Notes column wasn't found or is empty
                ah_text = ""
                if ah_col_idx < len(row):
                    ah_text = _cell_str(row[ah_col_idx].value)

                # The text we evaluate must come from the Notes column (or AH fallback),
                # NOT from the entire row — otherwise keyword matches can come from
                # unrelated cells like F&I Manager ("Marcus Hale") or amount columns.
                check_text = (notes_text + " " + ah_text).strip()

                # Reject placeholder-only content
                cleaned = check_text.replace("none", "").replace("nan", "").strip()
                if len(cleaned) <= 3:
                    continue

                all_found_notes.append(check_text)

                has_error = any(kw in check_text for kw in keywords_error)
                has_recap = any(kw in check_text for kw in keywords_recap)
                has_correct_amount = any(kw in check_text for kw in keywords_correct_amount)
                has_correct_source = any(kw in check_text for kw in keywords_correct_source)
                has_marcus = any(kw in check_text for kw in keywords_marcus)

                # HARD REQUIREMENT: $6,700 AND an error-indicator keyword must both appear
                # in the Notes column text. No pass without both.
                if not (has_correct_amount and has_error):
                    continue

                # Full pass: 6,700 + error + Marcus reference
                if has_marcus:
                    return {"pass": True, "score": 1.0, "feedback": f"Found Deal #10057 row in '{fpath.name}' sheet '{sheet_name}' with Notes indicating desk recap was in error, $6,700 is correct, and referencing Marcus Hale. Notes: {check_text[:300]}"}

                # Good pass: 6,700 + error + desk recap reference
                if has_recap:
                    return {"pass": True, "score": 1.0, "feedback": f"Found Deal #10057 row in '{fpath.name}' sheet '{sheet_name}' with Notes indicating desk recap error and $6,700 correct. Notes: {check_text[:300]}"}

                # Acceptable pass: 6,700 + error + correctness signal
                if has_correct_source:
                    return {"pass": True, "score": 1.0, "feedback": f"Found Deal #10057 row in '{fpath.name}' sheet '{sheet_name}' with Notes indicating error and $6,700 being correct. Notes: {check_text[:300]}"}

                # Partial: 6,700 + error but no Marcus/recap/correctness context
                return {"pass": True, "score": 0.8, "feedback": f"Found Deal #10057 row in '{fpath.name}' sheet '{sheet_name}' with $6,700 and error-indicator keywords but limited context. Notes: {check_text[:300]}"}

    if all_found_notes:
        return {"pass": False, "score": 0.0, "feedback": f"Found Deal #10057 row(s) but Notes column did not contain both $6,700 AND an error-indicator keyword as required. Found Notes text: {'; '.join(n[:200] for n in all_found_notes)}"}

    return {"pass": False, "score": 0.0, "feedback": f"No row found for Deal #10057 in any deal_log spreadsheet with Notes about desk recap error and $6,700 being correct. Files checked: {[f.name for f in deal_log_files]}"}

from pathlib import Path
import re
import datetime

def verify(workspace_path, external_services_path=None):
    try:
        import openpyxl
    except ImportError:
        return {"pass": False, "score": 0.0, "feedback": "openpyxl not available."}

    xlsx_files = list(Path(workspace_path).glob("*.xlsx")) + list(Path(workspace_path).glob("*.xlsm"))
    if not xlsx_files:
        return {"pass": False, "score": 0.0, "feedback": "No Excel files found in workspace."}

    # Look for cash exception log files first, then fall back to all Excel files
    target_files = [f for f in xlsx_files if "cash" in f.name.lower() or "exception" in f.name.lower()]
    if not target_files:
        target_files = xlsx_files

    def date_to_strs(cell_value):
        """Return multiple string representations for a date-like cell."""
        results = []
        if cell_value is None:
            return [""]
        if isinstance(cell_value, (datetime.datetime, datetime.date)):
            d = cell_value if isinstance(cell_value, datetime.date) else cell_value.date()
            results.append(d.strftime("%Y-%m-%d"))
            results.append(d.strftime("%m/%d/%Y"))
            results.append(d.strftime("%m/%d/%y"))  # MM/DD/YY
            results.append(f"{d.month}/{d.day}/{d.year}")
            results.append(f"{d.month}/{d.day}/{str(d.year)[-2:]}")
            results.append(d.strftime("%d-%b-%Y").lower())
            results.append(d.strftime("%b %d").lower())
            return results
        return [str(cell_value).lower().strip()]

    def check_date_match(cell_value, target_patterns):
        """Check if a cell value matches any of the target date patterns."""
        strs = date_to_strs(cell_value)
        for s in strs:
            for p in target_patterns:
                if p in s:
                    return True
        # Also check plain string
        plain = str(cell_value).lower().strip() if cell_value is not None else ""
        for p in target_patterns:
            if p in plain:
                return True
        return False

    def cell_str(cell_value):
        if cell_value is None:
            return ""
        return str(cell_value).lower().strip()

    # Rubric says deposit date 03/12/2027 and return date 03/25/2027
    # Accept both MM/DD/YYYY and MM/DD/YY and other common formats
    deposit_date_patterns = ["2027-03-12", "03/12/2027", "3/12/2027", "03/12/27", "3/12/27", "12-mar-2027", "12-mar", "mar 12"]
    return_date_patterns = ["2027-03-25", "03/25/2027", "3/25/2027", "03/25/27", "3/25/27", "25-mar-2027", "25-mar", "mar 25"]

    best_match = None
    best_missing = None
    best_row_num = None
    best_found_details = None

    for fpath in target_files:
        try:
            wb = openpyxl.load_workbook(fpath, data_only=True)
        except Exception:
            continue

        for sheet_name in wb.sheetnames:
            ws = wb[sheet_name]
            for row_idx, row in enumerate(ws.iter_rows(), start=1):
                # Build row text for keyword searching
                row_strs = []
                for cell in row:
                    row_strs.append(str(cell.value).lower() if cell.value is not None else "")
                row_text = " ".join(row_strs)

                # Quick check: must have patricia/morris or 10091
                has_patricia = "patricia" in row_text and "morris" in row_text
                has_deal = "10091" in row_text

                if not (has_patricia or has_deal):
                    continue

                missing = []
                found_details = []

                # Helper to get cell value by column index (1-indexed: A=1, D=4, etc.)
                def get_col(col_idx):
                    """Get cell value by 1-based column index from row tuple."""
                    if col_idx <= len(row):
                        return row[col_idx - 1].value
                    return None

                # Check customer name - Column E (index 5)
                col_e_val = cell_str(get_col(5))
                if "patricia" in col_e_val and "morris" in col_e_val:
                    found_details.append("Customer Patricia Morris in col E")
                elif "patricia" in row_text and "morris" in row_text:
                    found_details.append("Customer Patricia Morris found (not necessarily col E)")
                else:
                    missing.append("Customer Patricia Morris in column E")

                # Check deal number - Column D (index 4)
                col_d_val = cell_str(get_col(4))
                if "10091" in col_d_val:
                    found_details.append("Deal number 10091 in col D")
                elif "10091" in row_text:
                    found_details.append("Deal number 10091 found (not necessarily col D)")
                else:
                    missing.append("Deal number 10091 in column D")

                # Check amount - Column J (index 10)
                col_j_val = get_col(10)
                col_j_str = cell_str(col_j_val)
                col_j_numeric_match = False
                if isinstance(col_j_val, (int, float)):
                    if abs(col_j_val - 2300) < 1:
                        col_j_numeric_match = True
                if col_j_numeric_match or any(amt in col_j_str for amt in ["2300", "2,300"]):
                    found_details.append("Check amount $2,300 in col J")
                elif any(amt in row_text for amt in ["2300", "2,300"]):
                    found_details.append("Check amount $2,300 found (not necessarily col J)")
                else:
                    missing.append("Check amount $2,300 in column J")

                # Check reason - Column L (index 12)
                col_l_val = cell_str(get_col(12))
                if "closed" in col_l_val and ("account" in col_l_val or "acct" in col_l_val):
                    found_details.append("Return reason 'closed account' in col L")
                elif "closed" in col_l_val:
                    found_details.append("Return reason with 'closed' in col L")
                elif "closed" in row_text:
                    found_details.append("Return reason with 'closed' found (not necessarily col L)")
                else:
                    missing.append("Return reason 'closed account' or 'account closed' in column L")

                # Check deposit date (03/12/2027) - Column F (index 6)
                col_f_val = get_col(6)
                if check_date_match(col_f_val, deposit_date_patterns):
                    found_details.append("Deposit date 03/12/2027 in col F")
                else:
                    found_deposit_anywhere = False
                    for cell in row:
                        if check_date_match(cell.value, deposit_date_patterns):
                            found_deposit_anywhere = True
                            break
                    if found_deposit_anywhere:
                        found_details.append("Deposit date 03/12/2027 found (not necessarily col F)")
                    else:
                        missing.append("Original deposit date (03/12/2027) in column F")

                # Check return date (03/25/2027) - Column G (index 7)
                col_g_val = get_col(7)
                if check_date_match(col_g_val, return_date_patterns):
                    found_details.append("Return date 03/25/2027 in col G")
                else:
                    found_return_anywhere = False
                    for cell in row:
                        if check_date_match(cell.value, return_date_patterns):
                            found_return_anywhere = True
                            break
                    if found_return_anywhere:
                        found_details.append("Return date 03/25/2027 found (not necessarily col G)")
                    else:
                        missing.append("Return date (03/25/2027) in column G")

                if not missing:
                    return {
                        "pass": True,
                        "score": 1.0,
                        "feedback": f"Found complete cash exception log entry in file '{fpath.name}', sheet '{sheet_name}', row {row_idx}: {'; '.join(found_details)}."
                    }
                else:
                    if best_missing is None or len(missing) < len(best_missing):
                        best_missing = missing
                        best_match = (fpath.name, sheet_name)
                        best_row_num = row_idx
                        best_found_details = found_details

    if best_match and best_missing and len(best_missing) <= 2:
        return {
            "pass": False,
            "score": 0.5,
            "feedback": f"Found partial cash exception entry in '{best_match[0]}', sheet '{best_match[1]}', row {best_row_num}. Found: {'; '.join(best_found_details)}. Missing: {', '.join(best_missing)}"
        }

    if best_match and best_missing:
        return {
            "pass": False,
            "score": 0.2,
            "feedback": f"Found a row referencing Patricia Morris/10091 in '{best_match[0]}', sheet '{best_match[1]}', row {best_row_num} but missing {len(best_missing)} fields: {', '.join(best_missing)}. Found: {'; '.join(best_found_details)}"
        }

    return {
        "pass": False,
        "score": 0.0,
        "feedback": "No cash exception log entry found for Patricia Morris / Deal 10091 / $2,300 returned check with 'closed account' reason, deposit date 03/12/2027, and return date 03/25/2027. Searched files: " + ", ".join(f.name for f in target_files)
    }

from pathlib import Path
import json
import re

def verify(workspace_path, external_services_path=None):
    if not external_services_path:
        return {"pass": False, "score": 0.0, "feedback": "No external_services_path provided; cannot check mailbox or Slack."}

    marcus_notified = False
    elena_notified = False

    # Broad matching for email addresses / names
    marcus_ids = ["marcus", "marcus.hale", "marcushale", "hale"]
    elena_ids = ["elena", "elena.brooks", "elenabrooks", "brooks"]

    # Keywords that indicate the returned check context. Be loose: any two of these in the text is enough.
    returned_check_keywords = ["returned", "return", "2,300", "2300", "patricia", "morris", "10091", "closed account", "nsf", "bounced", "check", "cheque"]

    def text_has_returned_check_context(text):
        """Return True if the text contains at least 2 of the returned-check keywords."""
        matches = sum(1 for kw in returned_check_keywords if kw in text)
        return matches >= 2

    # ---- Check mailbox ----
    mailbox_path = Path(external_services_path) / "mailbox.json"
    if mailbox_path.exists():
        with open(mailbox_path, "r") as f:
            data = json.load(f)

        sent_emails = [e for e in data.get("emails", []) if e.get("folder", "").lower() == "sent"]

        for email in sent_emails:
            to_addr = (email.get("to_addr") or "").lower()
            cc_addr = (email.get("cc_addr") or "").lower()
            bcc_addr = (email.get("bcc_addr") or "").lower()
            body = (email.get("body_text") or "").lower()
            subject = (email.get("subject") or "").lower()
            combined_addr = to_addr + " " + cc_addr + " " + bcc_addr
            combined_text = body + " " + subject

            if not text_has_returned_check_context(combined_text):
                continue

            if any(m in combined_addr for m in marcus_ids):
                marcus_notified = True
            if any(e in combined_addr for e in elena_ids):
                elena_notified = True

    # ---- Check Slack ----
    slack_path = Path(external_services_path) / "slack_data.json"
    if slack_path.exists():
        with open(slack_path, "r") as f:
            slack_data = json.load(f)

        users = slack_data.get("users", {})

        # Build sets of user IDs for Marcus and Elena
        marcus_user_ids = set()
        elena_user_ids = set()
        for uid, u in users.items():
            name_lower = (u.get("name") or "").lower()
            real_name_lower = (u.get("real_name") or "").lower()
            email_lower = (u.get("profile", {}).get("email") or "").lower()
            combined_user = name_lower + " " + real_name_lower + " " + email_lower
            if any(m in combined_user for m in ["marcus", "hale"]):
                marcus_user_ids.add(uid)
            if any(e in combined_user for e in ["elena", "brooks"]):
                elena_user_ids.add(uid)

        messages = slack_data.get("messages", {})
        for channel_id, msgs in messages.items():
            if not isinstance(msgs, list):
                continue
            for msg in msgs:
                text = (msg.get("text") or "").lower()
                if not text_has_returned_check_context(text):
                    continue

                sender = msg.get("user", "")

                # Check if Marcus is the recipient (mentioned in text, or channel is a DM with Marcus)
                if any(m in text for m in ["marcus", "hale", "@marcus"]):
                    marcus_notified = True
                # If sent by someone TO a DM channel where Marcus is a member, or sender is marcus
                if sender in marcus_user_ids:
                    # Marcus sent it, so he's aware
                    marcus_notified = True

                if any(e in text for e in ["elena", "brooks", "@elena"]):
                    elena_notified = True
                if sender in elena_user_ids:
                    elena_notified = True

                # Also check channel members if available
                channels = slack_data.get("channels", {})
                channel_info = channels.get(channel_id, {})
                channel_members = channel_info.get("members", [])
                # If it's a DM (is_im or is_mpim) and Marcus/Elena are members
                if channel_info.get("is_im") or channel_info.get("is_mpim") or channel_info.get("is_group"):
                    if any(uid in marcus_user_ids for uid in channel_members):
                        marcus_notified = True
                    if any(uid in elena_user_ids for uid in channel_members):
                        elena_notified = True

                # Check if the DM channel name or id hints at the user
                channel_name = (channel_info.get("name") or "").lower()
                if any(m in channel_name for m in ["marcus", "hale"]):
                    marcus_notified = True
                if any(e in channel_name for e in ["elena", "brooks"]):
                    elena_notified = True

    if marcus_notified and elena_notified:
        return {"pass": True, "score": 1.0, "feedback": "Both Marcus Hale and Elena Brooks were notified about the returned check for Patricia Morris / Deal 10091 / $2,300."}
    elif marcus_notified:
        return {"pass": False, "score": 0.4, "feedback": "Marcus Hale was notified but Elena Brooks was NOT notified about the returned check for Patricia Morris / Deal 10091 / $2,300. Both must be notified per SOP."}
    elif elena_notified:
        return {"pass": False, "score": 0.4, "feedback": "Elena Brooks was notified but Marcus Hale was NOT notified about the returned check for Patricia Morris / Deal 10091 / $2,300. Both must be notified per SOP."}
    else:
        return {"pass": False, "score": 0.0, "feedback": "Neither Marcus Hale nor Elena Brooks were notified about the returned check for Patricia Morris / Deal 10091 / $2,300. No relevant sent emails or Slack messages found."}

