from pathlib import Path
import re

_DEAL_LOG_RE = re.compile(
    r"^deal[\s_-]*log(?P<suffix>.*)$",
    re.IGNORECASE,
)
_VERSION_RE = re.compile(
    r"^[\s_-]*v(?P<version>\d+)$",
    re.IGNORECASE,
)
_EXCLUDED_ARTIFACT_WORDS = {
    "archive", "archived", "archives", "backup", "backups", "bak", "baks",
    "copy", "copies", "decoy", "history", "historical", "old", "original",
    "preedit", "stale", "temp", "tmp",
}


def _normalized_words(value):
    value = re.sub(r"(?<=[a-z0-9])(?=[A-Z])", " ", str(value))
    return re.sub(r"[^a-z0-9]+", " ", value.lower()).strip().split()


def _has_excluded_marker(value):
    words = _normalized_words(value)
    if any(word in _EXCLUDED_ARTIFACT_WORDS for word in words):
        return True
    return any(
        words[index:index + 2] == ["pre", "edit"]
        for index in range(max(0, len(words) - 1))
    )


def _is_excluded_artifact(root, path, suffix):
    relative = path.relative_to(root)
    return _has_excluded_marker(suffix) or any(
        _has_excluded_marker(part) for part in relative.parts[:-1]
    )


def _select_deal_log(workspace_path):
    """Select one canonical final deal log without reading workbook content."""
    root = Path(workspace_path)
    matches = []
    excluded = []

    for path in root.glob("**/*"):
        if not path.is_file() or path.suffix.lower() not in {".xlsx", ".xlsm"}:
            continue

        match = _DEAL_LOG_RE.fullmatch(path.stem)
        if not match:
            continue

        suffix = match.group("suffix")
        if _is_excluded_artifact(root, path, suffix):
            excluded.append(path)
        else:
            matches.append((path, suffix))

    if not matches:
        if excluded:
            return None, "Only stale/decoy/backup deal-log workbooks found; no final artifact."
        return None, "No deal-log workbook found."

    source_files = [
        path for path, suffix in matches if not suffix.strip(" _-")
    ]
    revisions = [
        (path, suffix) for path, suffix in matches if suffix.strip(" _-")
    ]

    if not revisions:
        selected = source_files
    else:
        versioned = []
        for path, suffix in revisions:
            version_match = _VERSION_RE.fullmatch(suffix)
            if version_match:
                versioned.append((int(version_match.group("version")), path))

        if versioned:
            highest_version = max(version for version, _ in versioned)
            selected = sorted(
                path for version, path in versioned if version == highest_version
            )
        elif len(revisions) == 1:
            # Clear descriptive revisions such as Final or Approved are valid.
            selected = [revisions[0][0]]
        else:
            names = sorted(str(path.relative_to(root)) for path, _ in revisions)
            return None, f"Ambiguous deal-log revisions: {names}"

    if len(selected) != 1:
        names = sorted(str(path.relative_to(root)) for path in selected)
        return None, f"Ambiguous final deal-log artifact: {names}"

    return selected[0], None

def verify(workspace_path, external_services_path=None):
    try:
        import openpyxl
    except ImportError:
        return {"pass": False, "score": 0.0, "feedback": "openpyxl not available."}

    def _cell_str(v):
        return str(v).strip().lower() if v is not None else ""

    # Bind this criterion to the deterministic final deal-log artifact.
    fpath, selection_error = _select_deal_log(workspace_path)
    if selection_error:
        return {"pass": False, "score": 0.0, "feedback": selection_error}

    # Keep the existing verification loop, but bind it to one selected artifact.
    xlsx_files = [fpath]

    for fpath in xlsx_files:
        try:
            wb = openpyxl.load_workbook(fpath, data_only=True)
        except Exception as e:
            continue

        # Look for a sheet that matches Q1 2027 (be lenient with naming)
        target_sheet = None
        for sheet_name in wb.sheetnames:
            sn_lower = sheet_name.strip().lower()
            if "q1" in sn_lower and "2027" in sn_lower:
                target_sheet = sheet_name
                break

        if target_sheet is None:
            # Also try sheets that just say "q1 2027" or similar
            for sheet_name in wb.sheetnames:
                sn_lower = sheet_name.strip().lower().replace(" ", "")
                if "q12027" in sn_lower:
                    target_sheet = sheet_name
                    break

        if target_sheet is None:
            continue

        ws = wb[target_sheet]
        rows = list(ws.iter_rows())
        if not rows:
            continue

        # Column AG is the 33rd column (1-indexed), so 0-indexed it's 32
        ag_col_idx = 32  # 0-based index for column AG

        # Check every cell in column AG for the expected value
        found_values_ag = []
        for row in rows:
            if ag_col_idx < len(row):
                # Filter to only check deal #10091's row
                deal_num = row[0].value
                deal_str = str(deal_num).strip() if deal_num else ""
                if deal_str != "10091":
                    continue
                cell_val = row[ag_col_idx].value
                cell_str = _cell_str(cell_val)
                found_values_ag.append(cell_val)

                # Be lenient: check if cell contains 'held' and 'returned check' (case insensitive)
                if "held" in cell_str and "returned check" in cell_str:
                    return {
                        "pass": True,
                        "score": 1.0,
                        "feedback": f"Found 'Held - Returned Check' in Column AG (Title Status) of sheet '{target_sheet}' in file '{fpath.name}'. Cell value: '{cell_val}'."
                    }

        # Secondary check: also look at header row to find a column labeled 'Title Status'
        # in case columns have been shifted
        header_row = rows[0] if rows else []
        title_status_col_idx = None
        for idx, cell in enumerate(header_row):
            val = _cell_str(cell.value)
            if "title status" in val or "title_status" in val or val == "title":
                title_status_col_idx = idx
                break

        if title_status_col_idx is not None and title_status_col_idx != ag_col_idx:
            for row in rows[1:]:
                if title_status_col_idx < len(row):
                    # Filter to only check deal #10091's row
                    deal_num = row[0].value
                    deal_str = str(deal_num).strip() if deal_num else ""
                    if deal_str != "10091":
                        continue
                    cell_val = row[title_status_col_idx].value
                    cell_str = _cell_str(cell_val)
                    if "held" in cell_str and "returned check" in cell_str:
                        return {
                            "pass": True,
                            "score": 1.0,
                            "feedback": f"Found 'Held - Returned Check' in Title Status column (col index {title_status_col_idx}) of sheet '{target_sheet}' in file '{fpath.name}'. Cell value: '{cell_val}'."
                        }

        # Collect AG column non-empty values for feedback
        non_empty_ag = [str(v) for v in found_values_ag if v is not None and str(v).strip() != ""]
        return {
            "pass": False,
            "score": 0.0,
            "feedback": f"Sheet '{target_sheet}' in file '{fpath.name}' was found, but Column AG (Title Status) does not contain 'Held - Returned Check'. Non-empty AG column values found: {non_empty_ag[:20]}"
        }

    return {
        "pass": False,
        "score": 0.0,
        "feedback": f"Could not find a 'Q1 2027' sheet in any spreadsheet file in workspace. Files checked: {[f.name for f in xlsx_files]}"
    }

