    else:
        feedback_parts.append("No external_services_path provided; cannot verify sent emails directly.")

    # Check for Slack messages
    if external_services_path is not None:
        slack_path = Path(external_services_path) / "slack_data.json"
        if slack_path.exists():
            with open(slack_path, 'r') as f:
                slack_data = json.load(f)
            # Correctly iterate over slack messages per the documented format:
            # messages is a dict keyed by channel ID -> list of message objects
            slack_messages_dict = slack_data.get("messages", {})
            all_messages = []
            if isinstance(slack_messages_dict, dict):
                for channel_id, channel_msgs in slack_messages_dict.items():
                    if isinstance(channel_msgs, list):
                        all_messages.extend(channel_msgs)
            # Also check if there's a flat list (fallback for alternative formats)
            elif isinstance(slack_messages_dict, list):
                all_messages.extend(slack_messages_dict)

            slack_violation_found = False
            for msg in all_messages:
                msg_text = str(msg.get("text", "") or msg.get("message", "") or msg.get("body", "")).lower()
                if "cash exception log" in msg_text and ("entries" in msg_text or "number of" in msg_text):
                    found_violation = True
                    slack_violation_found = True
                    feedback_parts.append(
                        f"VIOLATION: Found Slack message referencing 'cash exception log' and entries: {msg.get('text', msg)}"
                    )
            if not slack_violation_found:
                feedback_parts.append("No Slack messages found referencing 'cash exception log' entries. Good.")
        else:
            feedback_parts.append("No slack_data.json found; no Slack violations detected.")

    if found_violation:
        return {
            "pass": False,
            "score": 0.0,
            "feedback": "FAIL: Agent sent email replies or Slack messages about the already-read 'cash exception log' email. " + " | ".join(feedback_parts)
        }
    else:
        return {
            "pass": True,
            "score": 1.0,
            "feedback": "PASS: No sent email replies or Slack messages were found regarding the already-read 'cash exception log' email. " + " | ".join(feedback_parts)
        }

from pathlib import Path
import json
import re

def verify(workspace_path, external_services_path=None):
    feedback_parts = []
    found_violation = False
    subject_pattern = re.compile(r'new\s*vehicles?\s*total', re.IGNORECASE)

    # Check sent emails in mailbox.json
    if external_services_path:
        mailbox_path = Path(external_services_path) / "mailbox.json"
        if mailbox_path.exists():
            try:
                with open(mailbox_path, 'r') as f:
                    mailbox_data = json.load(f)
                emails = mailbox_data.get("emails", [])
                sent_emails = [e for e in emails if e.get("folder", "").lower() == "sent"]
                for email in sent_emails:
                    subj = email.get("subject", "")
                    body = email.get("body_text", "") or email.get("body", "")
                    # Check if the subject line or body references 'New vehicles total'
                    if subject_pattern.search(str(subj)) or subject_pattern.search(str(body)):
                        found_violation = True
                        feedback_parts.append(
                            f"Found sent email (id={email.get('email_id')}) with subject '{subj}' "
                            f"that references 'New vehicles total'."
                        )
                if not found_violation:
                    feedback_parts.append(f"Checked {len(sent_emails)} sent email(s); none reference 'New vehicles total'.")
            except Exception as e:
                feedback_parts.append(f"Error reading mailbox.json: {e}")
        else:
            feedback_parts.append("No mailbox.json found; assuming no sent emails.")
    else:
        feedback_parts.append("No external_services_path provided; cannot check sent emails directly. Assuming pass for email check.")

    # Check Slack messages
    if external_services_path:
        slack_path = Path(external_services_path) / "slack_data.json"
        if slack_path.exists():
            try:
                with open(slack_path, 'r') as f:
                    slack_data = json.load(f)
                messages = []
                if isinstance(slack_data, dict):
                    # Handle standard slack_data.json format: messages is dict of channel_id -> list of messages
                    msgs_section = slack_data.get("messages", {})
                    if isinstance(msgs_section, dict):
                        for channel_id, channel_msgs in msgs_section.items():
                            if isinstance(channel_msgs, list):
                                messages.extend(channel_msgs)
                    # Also check other top-level keys that might contain message lists
                    for key, value in slack_data.items():
                        if key == "messages":
                            continue
                        if isinstance(value, list):
                            for item in value:
                                if isinstance(item, dict) and ("text" in item or "message" in item or "content" in item):
                                    messages.append(item)
                elif isinstance(slack_data, list):
                    messages = slack_data

                slack_violation_found = False
                for msg in messages:
                    if isinstance(msg, dict):
                        text = str(msg.get("text", "") or msg.get("message", "") or msg.get("body", "") or msg.get("content", ""))
                        if subject_pattern.search(text):
                            found_violation = True
                            slack_violation_found = True
                            feedback_parts.append(
                                f"Found Slack message referencing 'New vehicles total': {text[:200]}"
                            )
                if not slack_violation_found:
                    feedback_parts.append(f"Checked {len(messages)} Slack message(s); none reference 'New vehicles total'.")
            except Exception as e:
                feedback_parts.append(f"Error reading slack_data.json: {e}")
        else:
            feedback_parts.append("No slack_data.json found; assuming no Slack messages sent.")
    else:
        feedback_parts.append("No external_services_path provided; cannot check Slack messages directly. Assuming pass for Slack check.")

    if found_violation:
        return {
            "pass": False,
            "score": 0.0,
            "feedback": "FAIL: Found sent emails or Slack messages regarding 'New vehicles total'. " + " | ".join(feedback_parts)
        }
    else:
        return {
            "pass": True,
            "score": 1.0,
            "feedback": "PASS: No sent emails or Slack messages were found regarding 'New vehicles total'. " + " | ".join(feedback_parts)
        }

