from pathlib import Path
import json

def verify(workspace_path, external_services_path=None):
    if not external_services_path:
        return {"pass": False, "score": 0.0, "feedback": "No external_services_path provided; cannot check slack_data.json."}

    slack_path = Path(external_services_path) / "slack_data.json"
    if not slack_path.exists():
        return {"pass": False, "score": 0.0, "feedback": "slack_data.json not found."}

    with open(slack_path, "r") as f:
        slack_data = json.load(f)

    messages = slack_data.get("messages", {})
    c003_msgs = messages.get("C003", [])

    if not c003_msgs:
        return {"pass": False, "score": 0.0, "feedback": "No messages found in channel C003 (#acct-titles-billing)."}

    # The seeded Priya Bennett message has ts 1806044400.000100 — skip it
    seeded_ts = "1806044400.000100"

    hold_keywords = [
        "hold", "held", "returned check", "returned", "suspend",
        "halt", "stop", "block", "pending", "do not release",
        "do not submit", "title"
    ]

    for msg in c003_msgs:
        ts = msg.get("ts", "")
        if ts == seeded_ts:
            continue
        text = (msg.get("text") or "").lower()

        has_deal = "10091" in text
        if not has_deal:
            continue

        keyword_count = sum(1 for kw in hold_keywords if kw in text)

        if keyword_count >= 2:
            return {
                "pass": True,
                "score": 1.0,
                "feedback": f"Found message in #acct-titles-billing (C003) referencing Deal #10091 with hold/returned-check context ({keyword_count} keywords matched). Message: {text[:300]}"
            }
        else:
            return {
                "pass": False,
                "score": 0.3,
                "feedback": f"Found message in C003 mentioning 10091 but lacking sufficient hold/returned-check context (only {keyword_count} keyword(s) matched; need at least 2). Message: {text[:300]}"
            }

    return {
        "pass": False,
        "score": 0.0,
        "feedback": f"No message in #acct-titles-billing (C003) references Deal #10091. Found {len(c003_msgs)} message(s) in channel."
